function maxScore(nums) {
  const n = nums.length;
  const next = new Array(n).fill(n - 1);
  for (let i = n - 2; i >= 0; i--) {
    next[i] = nums[i] > nums[next[i + 1]] ? i : next[i + 1];
  }
  let score = 0;
  let position = 0;
  while (position < n - 1) {
    const target = next[position + 1];
    score += (target - position) * nums[target];
    position = target;
  }
  return score;
}

