function maxScore(nums) {
  // best[j] is the highest score of any hop sequence from index 0 that lands on j.
  const n = nums.length;
  const best = new Array(n).fill(-Infinity);
  best[0] = 0;
  for (let j = 1; j < n; j++)
    for (let i = 0; i < j; i++)
      best[j] = Math.max(best[j], best[i] + (j - i) * nums[j]);
  return best[n - 1];
}

