function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 2 + Math.floor(rand() * 7);
  const high = large || rand() < 0.5 ? 100000 : 5;
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * high));
  const shape = rand();
  if (shape < 0.15) nums.sort((a, b) => a - b);
  else if (shape < 0.3) nums.sort((a, b) => b - a);
  return [nums];
}
